{
  "implementation": "def solve(case):
    attempts = case.get('attempts', [])
    max_attempts = case.get('max_attempts')
    n = len(attempts)
    for attempt in attempts:
        if attempt.get('success') == True:
            return {
                'decision': 'stop',
                'memory_append': None,
                'next_attempt': n
            }
    if n >= max_attempts:
        last = attempts[-1]
        return {
            'decision': 'stop',
            'memory_append': {'reflection': last['reflection'], 'signature': last['failure_signature']},
            'next_attempt': n
        }
    if n > 0:
        last_sig = attempts[-1]['failure_signature']
        for i in range(n-1):
            if attempts[i]['failure_signature'] == last_sig:
                last = attempts[-1]
                return {
                    'decision': 'stop',
                    'memory_append': {'reflection': last['reflection'], 'signature': last['failure_signature']},
                    'next_attempt': n
                }
    if n == 0:
        return {
            'decision': 'continue',
            'memory_append': None,
            'next_attempt': 0
        }
    last = attempts[-1]
    return {
        'decision': 'continue',
        'memory_append': {'reflection': last['reflection'], 'signature': last['failure_signature']},
        'next_attempt': n
    }"
}
